import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u04")
C = "A2-B1"

L(1, "Profissões", "Wat doe je voor werk? Ik ben verpleegkundige.",
  ["Dizer e perguntar a profissão"],
  vocab=[V("v-verpleegkundige","verpleegkundige","enfermeiro(a)","noun","de"), V("v-kok","kok","cozinheiro(a)","noun","de","koks"),
         V("v-ingenieur","ingenieur","engenheiro(a)","noun","de"), V("v-schoonmaker","schoonmaker","empregado(a) de limpeza","noun","de"),
         V("v-beroep","beroep","profissão","noun","het","beroepen")],
  ex=[("Wat doe je voor werk?","O que fazes profissionalmente?"),("Ik ben verpleegkundige.","Sou enfermeira."),("Mijn broer is kok.","O meu irmão é cozinheiro."),("Wat is uw beroep?","Qual é a sua profissão?")],
  gram=[G("g-beroep-zonder-een","Profissão sem artigo","Como em português, diz-se **Ik ben kok** (sem *een*). Com adjetivo, usa-se o artigo: *Hij is **een goede** kok.* Muitas profissões têm forma feminina (*kok/kokkin*, *schoonmaker/schoonmaakster*), mas a forma neutra é cada vez mais usada para todos.",
    [("Zij is ingenieur.","Ela é engenheira."),("Hij is een goede leraar.","Ele é um bom professor.")])],
  review=["v-werk","v-werken","v-leraar","v-student"],
  cefr=C, exs=[
    MA([("verpleegkundige","enfermeiro"),("kok","cozinheiro"),("ingenieur","engenheiro"),("schoonmaker","empregado de limpeza")], "Profissões.", ["v-verpleegkundige","v-kok","v-ingenieur","v-schoonmaker"]),
    TR("pt-nl","O que fazes profissionalmente?", ["Wat doe je voor werk","Wat doe jij voor werk"], "Pergunta habitual.", ["v-beroep"]),
    TR("pt-nl","Sou enfermeira.", ["Ik ben verpleegkundige"], "Sem artigo.", ["v-verpleegkundige"]),
    TR("nl-pt","Hij is een goede kok.", ["Ele é um bom cozinheiro"], "Com adjetivo → artigo.", ["v-kok"]),
    AR("beroep","a profissão","het", "Het beroep.", ["v-beroep"]),
    FE(["Ik","ben","een","ingenieur","en","ik","werk","in","Delft."], 2, "Ik ben ingenieur", "Profissão sem adjetivo: Ik ben ingenieur.", ["v-ingenieur"]),
    MC("Qual é a pergunta formal?", ["*Wat is uw beroep?","Wat doe jij?|Informal e vaga.","Wie ben je?|Pergunta quem é, não a profissão."], "uw beroep.", ["v-beroep"]),
    LI("Mijn zus is schoonmaker in een ziekenhuis.", ["Mijn zus is schoonmaker in een ziekenhuis"], "A minha irmã é empregada de limpeza num hospital.", "schoonmaker.", ["v-schoonmaker"]),
    DL([("Buurman","Wat doe jij eigenlijk voor werk?","Afinal o que fazes profissionalmente?"),("Ana","")], ["*Ik ben verpleegkundige in het UMC.","Ik ben een werk.|Não faz sentido.","Ik doe werk.|Não responde."], "Dizer a profissão.", ["v-verpleegkundige"]),
    FB("Hij werkt als ___ in een restaurant.", ["kok"], "werken als = trabalhar como.", ["v-kok"], choices=["kok","beroep","werk"], tr="Ele trabalha como cozinheiro num restaurante."),
  ], diff=3, mins=6)

L(2, "Locais de trabalho", "Ik werk bij een bank / in een fabriek / op kantoor.",
  ["Dizer onde se trabalha com bij, in e op"],
  vocab=[V("v-kantoor","kantoor","escritório","noun","het","kantoren"), V("v-fabriek","fabriek","fábrica","noun","de"),
         V("v-bedrijf","bedrijf","empresa","noun","het","bedrijven"), V("v-werkgever","werkgever","empregador","noun","de"),
         V("v-werknemer","werknemer","trabalhador|funcionário","noun","de")],
  ex=[("Ik werk bij een groot bedrijf.","Trabalho numa empresa grande."),("Ze werkt op kantoor.","Ela trabalha no escritório."),("Mijn vader werkte in een fabriek.","O meu pai trabalhava numa fábrica."),("Het bedrijf heeft 200 werknemers.","A empresa tem 200 trabalhadores.")],
  gram=[G("g-bij-in-op-werk","bij / in / op","**bij** + nome da empresa ou organização: *Ik werk bij Philips / bij de gemeente.* **in** + edifício/local: *in een fabriek, in een ziekenhuis.* **op** em expressões fixas: *op kantoor, op school.*",
    [("Ik werk bij een bank.","Trabalho num banco (para um banco)."),("Hij zit op kantoor.","Ele está no escritório.")],
    "Em português usamos quase sempre «em»; em neerlandês a preposição depende do tipo de lugar.")],
  review=["v-werken","v-ziekenhuis","v-collega","v-gemeente"],
  cefr=C, exs=[
    MA([("kantoor","escritório"),("fabriek","fábrica"),("bedrijf","empresa"),("werkgever","empregador"),("werknemer","trabalhador")], "Locais e pessoas.", ["v-kantoor","v-fabriek","v-bedrijf","v-werkgever","v-werknemer"]),
    FB("Ik werk ___ een groot bedrijf.", ["bij"], "Organização → bij.", ["v-bedrijf"], choices=["bij","op","aan"], tr="Trabalho numa empresa grande."),
    FB("Ze werkt vandaag ___ kantoor.", ["op"], "Expressão fixa: op kantoor.", ["v-kantoor"], choices=["op","bij","naar"], tr="Ela hoje trabalha no escritório."),
    FB("Mijn vader werkte ___ een fabriek.", ["in"], "Edifício → in.", ["v-fabriek"], choices=["in","op","bij"], tr="O meu pai trabalhava numa fábrica."),
    AR("bedrijf","a empresa","het", "Het bedrijf.", ["v-bedrijf"]),
    AR("fabriek","a fábrica","de", "De fabriek.", ["v-fabriek"]),
    TR("pt-nl","Trabalho para a câmara municipal.", ["Ik werk bij de gemeente"], "bij de gemeente.", []),
    TR("nl-pt","Het bedrijf heeft 200 werknemers.", ["A empresa tem 200 [trabalhadores|funcionários|empregados]"], "werknemer.", ["v-werknemer"]),
    MC("Werkgever é…", ["*quem dá emprego","quem procura emprego|Isso é «werkzoekende».","um colega|Isso é «collega»."], "werk + gever (quem dá).", ["v-werkgever"]),
    LI("Ik werk al tien jaar bij hetzelfde bedrijf.", ["Ik werk al tien jaar bij hetzelfde bedrijf"], "Trabalho há dez anos na mesma empresa.", "al + presente.", ["v-bedrijf"]),
  ], diff=3, mins=6)

L(3, "Tarefas e responsabilidades", "Ik ben verantwoordelijk voor… Ik moet vaak…",
  ["Descrever tarefas do trabalho"],
  vocab=[V("v-verantwoordelijk","verantwoordelijk (voor)","responsável (por)","adjective"), V("v-taak","taak","tarefa","noun","de","taken"),
         V("v-klant","klant","cliente","noun","de","klanten"), V("v-vergadering","vergadering","reunião","noun","de"),
         V("v-regelen","regelen","tratar de|organizar","verb")],
  ex=[("Ik ben verantwoordelijk voor de planning.","Sou responsável pelo planeamento."),("Ik help klanten aan de telefoon.","Ajudo clientes ao telefone."),("Ik heb vandaag drie vergaderingen.","Hoje tenho três reuniões."),("Ik regel de afspraken.","Trato das marcações.")],
  review=["v-helpen","v-telefoon","v-afspraak"],
  cefr=C, exs=[
    MA([("verantwoordelijk","responsável"),("taak","tarefa"),("klant","cliente"),("vergadering","reunião"),("regelen","tratar de")], "No trabalho.", ["v-verantwoordelijk","v-taak","v-klant","v-vergadering","v-regelen"]),
    TR("pt-nl","Sou responsável pelo planeamento.", ["Ik ben verantwoordelijk voor de planning"], "verantwoordelijk voor.", ["v-verantwoordelijk"]),
    TR("nl-pt","Ik heb vandaag drie vergaderingen.", ["Hoje tenho três reuniões","Tenho três reuniões hoje"], "vergadering.", ["v-vergadering"]),
    FB("Ik ben verantwoordelijk ___ de klanten.", ["voor"], "verantwoordelijk voor.", ["v-verantwoordelijk"], choices=["voor","van","aan"], tr="Sou responsável pelos clientes."),
    AR("taak","a tarefa","de", "De taak.", ["v-taak"]),
    MC("Plural de «taak»:", ["*taken","taaken|Vogal longa em sílaba aberta escreve-se com uma só letra.","taaks|Não."], "taak → taken.", ["v-taak"]),
    WO("Trato das marcações.", ["Ik","regel","de","afspraken"], "regelen.", ["v-regelen"]),
    LI("Wat zijn je belangrijkste taken?", ["Wat zijn je belangrijkste taken","Wat zijn jouw belangrijkste taken"], "Quais são as tuas tarefas mais importantes?", "taken.", ["v-taak"]),
    CO("text","Mijn werkdag", "Ik werk bij een reisbureau in Utrecht. Ik help klanten aan de telefoon en per e-mail. Ik ben ook verantwoordelijk voor de boekingen van groepen. Op maandag hebben we altijd een vergadering met het hele team.",
       [("Onde trabalha?", ["*Numa agência de viagens","Num hotel","Num aeroporto"]),("Quando é a reunião de equipa?", ["*À segunda-feira","À sexta-feira","Todos os dias"])],
       "reisbureau = agência de viagens.", ["v-klant","v-vergadering","v-verantwoordelijk"]),
    SW("Descreva o seu trabalho (ou um trabalho que conhece) em 2–3 frases: onde, o quê e por que é responsável.", ["Ik werk bij een bank in Amsterdam. Ik help klanten en ik ben verantwoordelijk voor de nieuwe rekeningen."], ["Usou **bij/in/op** corretamente", "**verantwoordelijk voor**", "Pelo menos uma tarefa"], 12, "Descrever tarefas.", ["v-verantwoordelijk","v-taak"]),
  ], diff=3, mins=7)

L(4, "Horários e condições", "fulltime, parttime, een vast contract, overwerken",
  ["Falar de horário, contrato e condições de trabalho"],
  vocab=[V("v-fulltime","fulltime","a tempo inteiro","adjective"), V("v-parttime","parttime","a tempo parcial","adjective"),
         V("v-vast-contract","vast contract","contrato sem termo","expression",note="het (vaste) contract"), V("v-overwerken","overwerken","fazer horas extra","verb"),
         V("v-uur-per-week","uur per week","horas por semana","expression")],
  ex=[("Ik werk parttime, 24 uur per week.","Trabalho a tempo parcial, 24 horas por semana."),("Ze heeft een vast contract.","Ela tem um contrato sem termo."),("Ik moet vaak overwerken.","Tenho de fazer horas extra muitas vezes."),("Werk je fulltime?","Trabalhas a tempo inteiro?")],
  gram=[G("g-parttime-nl","Trabalho a tempo parcial","Nos Países Baixos trabalhar **parttime** é muito comum (homens e mulheres). Fala-se em **uur per week** (horas por semana) e em **een tijdelijk contract** (a termo) ou **een vast contract** (sem termo).",
    [("Ik werk vier dagen per week.","Trabalho quatro dias por semana.")])],
  review=["v-salaris","v-uur","v-werken"],
  cefr=C, exs=[
    MA([("fulltime","tempo inteiro"),("parttime","tempo parcial"),("vast contract","contrato sem termo"),("overwerken","fazer horas extra")], "Condições.", ["v-fulltime","v-parttime","v-vast-contract","v-overwerken"]),
    TR("pt-nl","Trabalho a tempo parcial, 24 horas por semana.", ["Ik werk parttime(,) 24 uur per week","Ik werk parttime(,) vierentwintig uur per week"], "uur per week (singular!).", ["v-parttime","v-uur-per-week"]),
    TR("nl-pt","Ze heeft een vast contract.", ["Ela tem um contrato sem termo","Ela tem um contrato efetivo","Ela tem contrato sem termo"], "vast contract.", ["v-vast-contract"]),
    FE(["Ik","werk","32","uren","per","week."], 3, "uur", "Depois de um número diz-se «uur»: 32 uur.", ["v-uur-per-week"]),
    MC("«Fazer horas extra» é…", ["*overwerken","overslapen|Isso é adormecer (dormir demais).","overstappen|Isso é mudar de transporte."], "overwerken.", ["v-overwerken"]),
    CJ("overwerken","ik","Gisteren heb ik twee uur ___.", ["overgewerkt"], "Separável: over-ge-werkt.", ["v-overwerken"], tense="passado-perfeito"),
    LI("Werk je fulltime of parttime?", ["Werk je fulltime of parttime","Werk jij fulltime of parttime"], "Trabalhas a tempo inteiro ou parcial?", "fulltime/parttime.", ["v-fulltime","v-parttime"]),
    DL([("Recruiter","Hoeveel uur per week wilt u werken?","Quantas horas por semana quer trabalhar?"),("Candidato","")], ["*Het liefst 32 uur, vier dagen per week.","Ik wil een vast contract.|Não responde às horas.","Ik werk al.|Não responde."], "Horas por semana.", ["v-uur-per-week"]),
    FB("Na een jaar kreeg ik een ___ contract.", ["vast"], "vast contract.", ["v-vast-contract"], choices=["vast","vaste","vasten"], tr="Ao fim de um ano recebi um contrato sem termo."),
    BS("Tenho de fazer horas extra muitas vezes.", ["Ik","moet","vaak","overwerken","overgewerkt"], ["Ik moet vaak overwerken"], "Modal + infinitivo; «overgewerkt» sobra.", ["v-overwerken"]),
  ], diff=3, mins=6)

L(5, "Gostar ou não do trabalho", "Ik vind mijn werk leuk, maar de reistijd is lang.",
  ["Dar opinião sobre o trabalho, com vantagens e desvantagens"],
  vocab=[V("v-afwisselend","afwisselend","variado","adjective"), V("v-stressvol","stressvol","stressante","adjective"),
         V("v-reistijd","reistijd","tempo de deslocação","noun","de"), V("v-sfeer","sfeer","ambiente","noun","de"),
         V("v-voordeel","voordeel","vantagem","noun","het","voordelen"), V("v-nadeel","nadeel","desvantagem","noun","het","nadelen")],
  ex=[("Mijn werk is afwisselend.","O meu trabalho é variado."),("De sfeer is goed.","O ambiente é bom."),("Het nadeel is de lange reistijd.","A desvantagem é o longo tempo de deslocação."),("Een voordeel is dat ik thuis kan werken.","Uma vantagem é que posso trabalhar em casa.")],
  review=["v-vinden","v-leuk","v-collega","v-thuiswerken"],
  cefr=C, exs=[
    MA([("afwisselend","variado"),("stressvol","stressante"),("reistijd","tempo de deslocação"),("sfeer","ambiente")], "Opinião sobre o trabalho.", ["v-afwisselend","v-stressvol","v-reistijd","v-sfeer"]),
    MA([("voordeel","vantagem"),("nadeel","desvantagem"),("afwisselend","variado")], "Prós e contras.", ["v-voordeel","v-nadeel"]),
    TR("pt-nl","O ambiente é bom.", ["De sfeer is goed"], "de sfeer.", ["v-sfeer"]),
    TR("nl-pt","Mijn werk is afwisselend, maar soms stressvol.", ["O meu trabalho é variado, mas às vezes [stressante|é stressante]"], "afwisselend / stressvol.", ["v-afwisselend","v-stressvol"]),
    AR("voordeel","a vantagem","het", "Het voordeel.", ["v-voordeel"]),
    WO("Uma vantagem é que posso trabalhar em casa.", ["Een","voordeel","is","dat","ik","thuis","kan","werken"], "dat + verbos no fim.", ["v-voordeel"]),
    FE(["Het","nadeel","is","dat","de","reistijd","lang","zijn."], 7, "is", "O sujeito é «de reistijd» (singular): dat de reistijd lang is.", ["v-nadeel"]),
    LI("Hoe is de sfeer op je werk?", ["Hoe is de sfeer op je werk","Hoe is de sfeer op jouw werk"], "Como é o ambiente no teu trabalho?", "sfeer.", ["v-sfeer"]),
    DL([("Vriend","Vind je je nieuwe baan leuk?","Gostas do teu novo emprego?"),("Sofia","")], ["*Ja, het werk is afwisselend en de collega's zijn aardig.","Ja, ik heb een nieuwe baan.|Não diz se gosta.","Nee, ik ben verpleegkundige.|Não responde à pergunta."], "Opinião com razões.", ["v-afwisselend"]),
    SW("Diga uma vantagem e uma desvantagem do seu trabalho ou estudos.", ["Een voordeel is dat het werk afwisselend is. Een nadeel is dat de reistijd lang is."], ["Usou **voordeel** e **nadeel**", "Depois de **dat**, verbo no fim", "Usou pelo menos um adjetivo da lição"], 12, "Prós e contras.", ["v-voordeel","v-nadeel"]),
  ], diff=3, mins=7)

W()
